mapper.select:
SELECT a.auction_id, a.start_price, a.current_price, a.status AS auction_status, a.bid_count, a.bidder_count, a.started_at, a.ended_at, p.product_id, p.title AS product_title, p.thumbnail_url, p.status AS product_status, o.order_id, o.buyer_id, buyer.nickname AS buyer_nickname, o.final_price, o.status AS order_status, o.created_at AS order_created_at FROM auction a JOIN product p ON p.product_id = a.product_id LEFT JOIN LATERAL ( SELECT latest_order.* FROM "order" latest_order WHERE latest_order.auction_id = a.auction_id ORDER BY latest_order.order_id DESC LIMIT 1 ) o ON TRUE LEFT JOIN member buyer ON buyer.member_id = o.buyer_id WHERE p.member_id = #{memberId}
AND a.status = #{auctionStatus}::auction_status
AND a.auction_id < #{cursor}
ORDER BY a.auction_id DESC LIMIT #{limit}
